export type ParsedClaimHeldInstruction<
  TProgram extends string = typeof INTENT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    wallet: TAccountMetas[0];
    intent: TAccountMetas[1];
    vault: TAccountMetas[2];
    inputMint: TAccountMetas[3];
    announcement: TAccountMetas[4];
    to: TAccountMetas[5];
    inputTokenProgram: TAccountMetas[6];
    mintCap?: TAccountMetas[7] | undefined;
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: ClaimHeldInstructionData;
};

export function parseClaimHeldInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimHeldInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === INTENT_ENGINE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      wallet: getNextAccount(),
      intent: getNextAccount(),
      vault: getNextAccount(),
      inputMint: getNextAccount(),
      announcement: getNextAccount(),
      to: getNextAccount(),
      inputTokenProgram: getNextAccount(),
      mintCap: getNextOptionalAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getClaimHeldInstructionDataDecoder().decode(instruction.data),
  };
}
